source_judgments = {}
for job, rep in reports.items():
    for s in rep['sources']:
        a = archives.get(s['url'], {})
        p = R/'source-artifacts/pages'/(a.get('artifact_id','missing')+'.txt')
        t = p.read_text(encoding='utf-8') if p.exists() else ''
        sid=s['source_id']; url=s['url']
        if not t or a.get('http_status') != 200:
            status='BLOCKED_OR_NOT_ARCHIVED'; inspection='Archive metadata inspected; no readable full source body'
        elif 'reddit.com' in url:
            status='HTTP200_EMPTY_REDDIT_SHELL'; inspection='Entire archived visible text inspected; contains only Reddit; no post/comments'
        elif 'counterpointresearch.com' in url:
            status='HTTP200_HEADER_ONLY'; inspection='Entire archived visible text inspected; headline/publication metadata/navigation without numeric evidence body'
        elif 'warc.com' in url:
            status='PUBLIC_SUMMARY_ONLY'; inspection='Entire public preview inspected; full Euromonitor report not available'
        elif any(d in url for d in ['grandviewresearch','imarcgroup','emergenresearch','expertmarketresearch','kenresearch','gminsights','asinsight']):
            status='ISSUER_PUBLIC_MODEL_OR_ESTIMATE_PREVIEW'; inspection='Public catalog/preview numerical passages and relevant scope inspected; paid underlying methods/dataset NOT inspected'
        elif 'cta.tech/research/' in url:
            status='PUBLIC_DATASET_CATALOG_AUTH_REQUIRED'; inspection='Public catalog description/pricing/access conditions inspected; no paid tables'
        else:
            status='PUBLIC_BODY_INSPECTED'; inspection='Relevant source body and date/taxonomy passages inspected; factual support evaluated individually in claim audit'
        source_judgments[(job,sid)] = dict(job_id=job,source_id=sid,url=url,title=s.get('title'),agent_published_at=s.get('published_at'),agent_retrieved_at=s.get('retrieved_at'),agent_access_state=s.get('access_state'),coordinator_access_status=status,inspection_method=inspection,http_status=a.get('http_status'),artifact_id=a.get('artifact_id'),archive_sha256=a.get('sha256'),archive_retrieved_at=a.get('retrieved_at'),archived_text_characters=len(t),claims_supported_agent=s.get('claims_supported',[]))

claim_audit=[]
for job,rep in reports.items():
    notes=A if job=='W1-A' else B
    for c in rep['claims']:
        status,note=notes[c['claim_id']]
        claim_audit.append(dict(job_id=job,claim_id=c['claim_id'],original_claim=c['claim'],original_classification=c.get('classification'),original_confidence=c.get('confidence'),source_ids=c['source_ids'],coordinator_status=status,coordinator_reason=note,source_access=[dict(source_id=sid,status=source_judgments[(job,sid)]['coordinator_access_status']) for sid in c['source_ids']],use_as_category_expenditure_weight=False))

