out={'audit_type':'independent_coordinator_verification_not_mg_research_replica','created_at':datetime.datetime.now(datetime.timezone.utc).isoformat(),'audited_jobs':['W1-A','W1-B'],'raw_inputs_sha256':{j:hashlib.sha256((R/'jobs'/j/'evidence.json').read_bytes()).hexdigest() for j in reports},'all_claims_reviewed':True,'all_sources_full_content_verified':False,'additional_web_requests':0,'overseas_sku_research_performed':False,'method':'Read original claims and report-specific numerical passages, archived public body/scope/date passages, all Counterpoint/WARC/Reddit visible text, inherited verification notes, and independently reproduced Census ZIP arithmetic. Public issuer previews verify what an issuer publishes, not underlying true market GMV; access status and claim validity kept separate. No peer evidence sent to unfinished mg replicas.','findings':findings,'source_audit':list(source_judgments.values()),'claim_audit':claim_audit,'census_recomputation':census_calculation,'inherited_root_checks':prior['checks'],'inherited_checks_warning':'Prior root checks included live-web reads not reproducible from blocked archives; retained as separate provenance, never described as this auditor own full-source inspection.','weight_policy':'Every use_as_category_expenditure_weight flag is false until common category/year/channel/unit/currency crosswalk reviewed. This does not reject real demand or all anchors.'}
(R/'w1-independent-coordinator-audit.json').write_text(json.dumps(out,ensure_ascii=False,indent=2),encoding='utf-8')
lines=['W1-A / W1-B independent coordinator audit','This is verification support, not an additional mg research replica.','All 41 structured claims reviewed; not all 70 source observations full-content verified.','No additional web calls, no overseas SKU lookup, no cookies/browser changes.','']
for f in findings: lines.extend([f"{f['id']} [{f['severity']}] {'; '.join(f['references'])}", f['finding'],''])
