for c in claim_audit: lines.extend([f"{c['job_id']}:{c['claim_id']} [{c['coordinator_status']}] sources={','.join(c['source_ids'])}",c['original_claim'],c['coordinator_reason'],''])
lines.append('SOURCE ACCESS AUDIT')
for s in source_judgments.values(): lines.extend([f"{s['job_id']}:{s['source_id']} [{s['coordinator_access_status']}] {s['url']}",s['inspection_method'],f"HTTP={s['http_status']} body_chars={s['archived_text_characters']} agent_access={s['agent_access_state']} published_agent={s['agent_published_at']} archive_sha={s['archive_sha256']}",''])
